def render(text, slots, flips):
    out = text
    for i, (ch, need, why) in enumerate(slots):
        put = need != (i in flips)
        out = out.replace('{%d}' % i, ch if put else '')
    return out
def wrongs_of(tpl, rng):
    text, slots, lv = tpl
    n = len(slots)
    cands = [frozenset([i]) for i in range(n)]
    cands += [frozenset(c) for c in itertools.combinations(range(n), 2)]
    rng.shuffle(cands)
    out = []
    for fl in cands:
        s = render(text, slots, fl)
        rs = []
        for i in sorted(fl):
            ch, need, why = slots[i]
            nm = {',': 'кому', ' —': 'тире', ':': 'двокрапку'}[ch]
            rs.append(('пропущено ' + nm if need else 'зайва ' + {',': 'кома', ' —': 'тире', ':': 'двокрапка'}[ch]) + ': ' + why)
        out.append((s, '; '.join(rs)))
    return out
def f_punct_right(T, rng, lv):
    pool = [t for t in TPL if t[2] == lv] or TPL
    t = rng.choice(pool)
    ok = render(t[0], t[1], frozenset())
    ws = wrongs_of(t, rng)
    singles = [w for w in ws if ';' not in w[1]][:3]
    wr = singles if len(singles) >= 3 else ws[:3]
    if len(wr) < 3: return False
    return T.add(lv, 'У якому реченні розділові знаки поставлено правильно?', ok, wr, 'у кожному варіанті зміщено лише один знак — перевіряй за правилом, а не за паузою', 'знаки поставлено за правилами: ' + '; '.join(s[2] for s in t[1] if s[1]))
def f_punct_wrong(T, rng, lv):
    pool = [t for t in TPL if t[2] == lv] or TPL
    t = rng.choice(pool); ws = wrongs_of(t, rng)
    bad, why = ws[0]
    others = [render(o[0], o[1], frozenset()) for o in rng.sample([o for o in TPL if o is not t], 3)]
    return T.add(lv, 'У якому реченні розділові знаки поставлено НЕправильно?', bad, [(o, 'розділові знаки розставлено правильно') for o in others], 'завдання навпаки: шукаємо помилку', why)
def f_commas(T, rng, lv):
    pool = [t for t in TPL if all(s[0] == ',' for s in t[1]) and t[2] == lv] or [t for t in TPL if all(s[0] == ',' for s in t[1])]
    t = rng.choice(pool); text, slots, _ = t
    n = sum(1 for s in slots if s[1])
    bare = render(text, slots, frozenset(range(len(slots)))) if False else text
    for i in range(len(slots)): bare = bare.replace('{%d}' % i, '')
    cand = []
    if n > 0: cand.append((n - 1, 'пропущено одну з необхідних ком'))
    cand.append((n + 1, 'поставлено зайву кому'))
    cand.append((n + 2, 'поставлено дві зайві коми'))
    if n > 1: cand.append((n - 2, 'пропущено дві необхідні коми'))
    cand.append((n + 3, 'поставлено три зайві коми'))
    wr = [(str(v), r) for v, r in cand if v >= 0 and v != n][:4]
    return T.add(lv, f'Скільки ком треба поставити в реченні «{bare}»?', str(n), wr[:3], 'зайві коми між підметом і присудком не ставимо', '; '.join(s[2] for s in slots if s[1]))

