SENT = [s for s in SENT if s[0] not in ('Я бачив птаха, що співав на гілці.', 'Ми зупинилися, бо почався дощ.', 'Він прийшов, щоб допомогти.' if False else '')]
SENT = [s for s in SENT if '(бо' not in s[1]]
def draw_card(txt, fname):
    c = Canvas(480, 120, 'Схема речення')
    c.rect(20, 40, 440, 60, fill='#f9fafb', stroke='#9ca3af', sw=2, rx=10)
    c.text(240, 80, txt, size=26, anchor='middle', bold=True)
    open(f'{IMGDIR}/{fname}.svg', 'w', encoding='utf-8').write(c.svg())
    return f'/img/ukrainian/{fname}.svg'
def f_img_scheme(T, rng, lv):
    pool = SENT if lv >= 2 else [s for s in SENT if s[2] != 'безсполучникове']
    s, sc, tp = rng.choice(pool)
    others = [x for x in SENT if x[1] != sc]
    ds = []; seen = {sc}
    for x in rng.sample(others, len(others)):
        if x[1] in seen: continue
        seen.add(x[1]); ds.append(x)
        if len(ds) == 3: break
    img = draw_card(sc, f'u6_{tag(sc)}')
    return T.add(lv, 'Якому реченню відповідає схема на малюнку?', s, [(x[0], f'схема цього речення: {x[1]}') for x in ds], 'кома, двокрапка й тире у схемі вказують на тип зв’язку між частинами', f'схема {sc}: {tp} речення', img=img)
def f_scheme_of(T, rng, lv):
    s, sc, tp = rng.choice(SENT)
    others = [x[1] for x in SENT if x[1] != sc]; others = list(dict.fromkeys(others))
    ds = rng.sample(others, 3)
    return T.add(lv, f'Яка схема відповідає реченню «{s}»?', sc, [(d, f'схемою {d} описано речення іншої будови') for d in ds], 'позначай головну частину квадратними, а підрядну — круглими дужками', f'будова: {tp} речення — {sc}')
TYPES = {'складносурядне': 'частини рівноправні, з’єднані сурядними сполучниками (і, а, але)', 'складнопідрядне': 'одна частина підпорядкована іншій підрядним сполучником чи сполучним словом', 'безсполучникове': 'частини з’єднані без сполучників, лише інтонацією та знаками'}
def f_type(T, rng, lv):
    s, sc, tp = rng.choice(SENT)
    wr = [(t, TYPES[t]) for t in TYPES if t != tp]
    wr.append(('просте ускладнене речення', 'у реченні дві граматичні основи — воно складне'))
    return T.add(lv, f'Укажіть тип складного речення: «{s}»', tp, [(a, f'це не так: {b}') for a, b in wr], 'тип визначаємо за способом зв’язку частин, а не за знаками', f'зв’язок: {TYPES[tp]}')

