SR = [[('Маленька', 'означення'), ('дівчинка', 'підмет'), ('читає', 'присудок'), ('цікаву', 'означення2'), ('книжку', 'додаток')],
      [('Мудрий', 'означення'), ('лікар', 'підмет'), ('допоміг', 'присудок'), ('хворому', 'додаток')], [('Золота', 'означення'), ('осінь', 'підмет'), ('прикрасила', 'присудок'), ('парк', 'додаток')],
      [('Наш', 'означення'), ('клас', 'підмет'), ('виграв', 'присудок'), ('конкурс', 'додаток')], [('Веселі', 'означення'), ('діти', 'підмет'), ('співали', 'присудок'), ('пісні', 'додаток')],
      [('Старий', 'означення'), ('дід', 'підмет'), ('читає', 'присудок'), ('газету', 'додаток')], [('Тепла', 'означення'), ('весна', 'підмет'), ('прийшла', 'присудок'), ('нарешті', 'обставина')],
      [('Вчитель', 'підмет'), ('уважно', 'обставина'), ('слухає', 'присудок'), ('учня', 'додаток')], [('Яскраве', 'означення'), ('сонце', 'підмет'), ('світило', 'присудок'), ('вранці', 'обставина')]]
ROLE_Q = {'підмет': 'хто? що? (виконує дію)', 'присудок': 'що робить? що з ним?', 'додаток': 'кого? чого? кому? чому? кого? що?', 'означення': 'який? чий?', 'обставина': 'як? де? коли?'}
def f_member(T, rng, lv):
    sent = rng.choice(SR)
    toks = [(w, 'означення' if r.startswith('означення') else r) for w, r in sent]
    full = ' '.join(w for w, r in toks)
    # унікальність ролі
    from collections import Counter
    cnt = Counter(r for w, r in toks)
    target = rng.choice([r for r in cnt if cnt[r] == 1 or r != 'означення'])
    if cnt[target] > 1: return False
    w0 = [w for w, r in toks if r == target][0]
    wr = [(w, f'це {r}: питання «{ROLE_Q[r]}»') for w, r in toks if r != target]
    name = {'підмет': 'підмет', 'присудок': 'присудок', 'додаток': 'додаток', 'означення': 'означення', 'обставина': 'обставину'}[target]
    return T.add(lv, f'Укажіть {name} у реченні «{full.capitalize() if False else full}.»', w0, wr[:4], 'підмет і додаток обидва — іменники, відрізняй за відмінком і значенням дії', f'«{w0}» відповідає на питання «{ROLE_Q[target]}» — {target}')

PRED = {'простий': [('Діти малюють.', ), ('Вітер дме.',), ('Сонце сходить.',), ('Ми співаємо.',)],
        'складений дієслівний': [('Я хочу малювати.',), ('Діти почали співати.',), ('Він уміє плавати.',), ('Вона любить читати.',)],
        'складений іменний': [('Він був учителем.',), ('Небо стало темним.',), ('Мама була щасливою.',), ('Брат є студентом.',)]}
PEX = {'простий': 'присудок виражений одним дієсловом у особовій формі', 'складений дієслівний': 'присудок складається з допоміжного дієслова та інфінітива', 'складений іменний': 'присудок складається з дієслова-зв’язки та іменної частини'}
def f_pred(T, rng, lv):
    k = rng.choice(list(PRED)); s = rng.choice(PRED[k])[0]
    wr = []
    for o in PRED:
        if o != k: wr.append((rng.choice(PRED[o])[0], f'у цьому реченні присудок {o}: {PEX[o]}'))
    wr.append((rng.choice(PRED[[o for o in PRED if o != k][0]])[0], 'присудок іншого типу'))
    wr = list(dict(wr).items())
    for o in PRED:
        for z in PRED[o]:
            if o != k and z[0] not in dict(wr) and len(wr) < 3: wr.append((z[0], f'у цьому реченні присудок {o}'))
    return T.add(lv, f'У якому реченні присудок {k}?', s, wr[:3], 'складений присудок має дві частини, простий — одну форму', PEX[k])

PUR = {'розповідне': ['Світить сонце.', 'Діти грають у парку.', 'Наступила осінь.', 'Мама готує вечерю.'], 'питальне': ['Яка сьогодні погода?', 'Де ти був учора?', 'Коли почнеться урок?', 'Хто прийшов першим?'],
       'спонукальне': ['Принеси мені книжку.', 'Не шуміть у класі.', 'Давайте почнемо роботу.', 'Відкрийте підручники.'], 'окличне': ['Як гарно тут!', 'Яка чудова погода!', 'Як я рада тебе бачити!']}
PEXP = {'розповідне': 'повідомляє про факт', 'питальне': 'містить запитання', 'спонукальне': 'містить наказ, прохання або заклик', 'окличне': 'виражає сильні почуття'}
def f_purpose(T, rng, lv):
    k = rng.choice(list(PUR)); s = rng.choice(PUR[k])
    wr = [(rng.choice(PUR[o]), f'це {o} речення: {PEXP[o]}') for o in PUR if o != k]
    if lv == 1: wr = wr[:3]
    return T.add(lv, f'Укажіть {k} речення.', s, wr, 'окличне речення може бути й питальним чи спонукальним, але тут ознака інтонації вирішальна', f'{k} речення {PEXP[k]}')

